  | otherwise = Error.maybeCryptoError $ do
      cipher <- Cipher.cipherInit key
      Cipher.aeadInit Cipher.AEAD_GCM (cipher :: AES.AES256) nonce

aes256GcmEncrypt :: B.ByteString -> B.ByteString -> B.ByteString -> B.ByteString -> B.ByteString
aes256GcmEncrypt key nonce plaintext associated = case gcm key nonce of
  Just aead -> let (tag, ciphertext) = Cipher.aeadSimpleEncrypt aead associated plaintext 16
               in ciphertext <> BA.convert (Cipher.unAuthTag tag)
  Nothing -> P.error "an AES-256-GCM key is 32 bytes and its nonce 12"

aes256GcmDecrypt :: B.ByteString -> B.ByteString -> B.ByteString -> B.ByteString -> Maybe B.ByteString
