-- | base_2b: the bytes as b-bit digits.
base2b :: B.ByteString -> Int -> Int -> [Int]
base2b x b count = go (B.unpack x) (0 :: Integer) 0 count
  where
    go _ _ _ 0 = []
    go bytes total bits n
      | bits < b = case bytes of
          byte : rest -> go rest (total * 256 + P.toInteger byte) (bits + 8) n
          [] -> P.error "base_2b: too few bytes"
      | otherwise = P.fromInteger ((total `Bits.shiftR` (bits - b)) `P.mod` (2 P.^ b)) : go bytes total (bits - b) (n - 1)

