  | otherwise =
      let left = xmssNode skSeed (2 * i) (z - 1) pkSeed a
          right = xmssNode skSeed (2 * i + 1) (z - 1) pkSeed a
      in hashN [pkSeed, addressBytes (typed tree a) { addressWord2 = P.fromIntegral z, addressWord3 = P.fromIntegral i }, left, right]

xmssSign :: B.ByteString -> B.ByteString -> Int -> B.ByteString -> Address -> B.ByteString
xmssSign message skSeed index pkSeed a =
