  in wotsSign message skSeed pkSeed (typed wotsHash a) { addressWord1 = P.fromIntegral index } <> B.concat path

-- | Climbs a tree from a leaf: the node, its index, and the siblings' path.
climb :: B.ByteString -> Address -> Int -> B.ByteString -> [B.ByteString] -> Int -> B.ByteString
climb pkSeed a index node siblings heightBase = go node index (P.zip [0 ..] siblings)
  where
    go current _ [] = current
    go current treeIndex ((k, sibling) : rest)
      | (index `Bits.shiftR` k) `P.mod` 2 == 0 =
          let next = treeIndex `P.div` 2
          in go (hashN [pkSeed, at next k, current, sibling]) next rest
      | otherwise =
          let next = (treeIndex - 1) `P.div` 2
          in go (hashN [pkSeed, at next k, sibling, current]) next rest
    at next k = addressBytes a { addressWord2 = P.fromIntegral (heightBase + k + 1), addressWord3 = P.fromIntegral next }

xmssPublicFromSignature :: Int -> B.ByteString -> B.ByteString -> B.ByteString -> Address -> B.ByteString
xmssPublicFromSignature index signature message pkSeed a =
  let leaf = wotsPublicFromSignature (B.take (slhLen * slhN) signature) message pkSeed (typed wotsHash a) { addressWord1 = P.fromIntegral index }
      siblings = [slice signature ((slhLen + k) * slhN) slhN | k <- [0 .. slhHp - 1]]
  in climb pkSeed (typed tree a) index leaf siblings 0

xmssBytes :: Int
xmssBytes = (slhLen + slhHp) * slhN

layers :: W.Word64 -> Int -> [(Int, W.Word64, Int)]
layers treeIndex leafIndex = P.take slhD (P.zip3 [0 ..] trees leaves)
  where
    trees = P.iterate (`Bits.shiftR` slhHp) treeIndex
    leaves = leafIndex : [P.fromIntegral (t `P.mod` 8) | t <- trees]

htSign :: B.ByteString -> B.ByteString -> B.ByteString -> W.Word64 -> Int -> B.ByteString
htSign message skSeed pkSeed treeIndex leafIndex = B.concat (go message (layers treeIndex leafIndex))
  where
    go _ [] = []
    go root ((j, t, leaf) : rest) =
      let a = zeroAddress { addressLayer = P.fromIntegral j, addressTree = t }
          signature = xmssSign root skSeed leaf pkSeed a
      in signature : go (xmssPublicFromSignature leaf signature root pkSeed a) rest

htVerify :: B.ByteString -> B.ByteString -> B.ByteString -> W.Word64 -> Int -> B.ByteString -> Bool
htVerify message signature pkSeed treeIndex leafIndex pkRoot = go message (layers treeIndex leafIndex) == pkRoot
  where
    go node [] = node
    go node ((j, t, leaf) : rest) =
      let a = zeroAddress { addressLayer = P.fromIntegral j, addressTree = t }
      in go (xmssPublicFromSignature leaf (slice signature (j * xmssBytes) xmssBytes) node pkSeed a) rest

forsSecret :: B.ByteString -> B.ByteString -> Address -> Int -> B.ByteString
forsSecret skSeed pkSeed a index =
  hashN [pkSeed, addressBytes (typed forsPrf a) { addressWord1 = addressWord1 a, addressWord3 = P.fromIntegral index }, skSeed]

forsNode :: B.ByteString -> Int -> Int -> B.ByteString -> Address -> B.ByteString
forsNode skSeed i z pkSeed a
  | z == 0 = hashN [pkSeed, addressBytes a { addressWord2 = 0, addressWord3 = P.fromIntegral i }, forsSecret skSeed pkSeed a i]
  | otherwise =
      let left = forsNode skSeed (2 * i) (z - 1) pkSeed a
          right = forsNode skSeed (2 * i + 1) (z - 1) pkSeed a
      in hashN [pkSeed, addressBytes a { addressWord2 = P.fromIntegral z, addressWord3 = P.fromIntegral i }, left, right]

forsSign :: B.ByteString -> B.ByteString -> B.ByteString -> Address -> B.ByteString
forsSign digest skSeed pkSeed a = B.concat
  [ forsSecret skSeed pkSeed a (i * 2 P.^ slhA + index) <>
      B.concat [forsNode skSeed (i * 2 P.^ (slhA - j) + ((index `Bits.shiftR` j) `Bits.xor` 1)) j pkSeed a | j <- [0 .. slhA - 1]]
  | (i, index) <- P.zip [0 ..] (base2b digest slhA slhK) ]

forsPublicFromSignature :: B.ByteString -> B.ByteString -> B.ByteString -> Address -> B.ByteString
forsPublicFromSignature signature digest pkSeed a =
  let roots =
        [ let offset = i * (slhA + 1) * slhN
              leafIndex = i * 2 P.^ slhA + index
              leaf = hashN [pkSeed, addressBytes a { addressWord2 = 0, addressWord3 = P.fromIntegral leafIndex }, slice signature offset slhN]
              siblings = [slice signature (offset + (j + 1) * slhN) slhN | j <- [0 .. slhA - 1]]
          in climbFors leafIndex index leaf siblings
        | (i, index) <- P.zip [0 ..] (base2b digest slhA slhK) ]
  in hashN (pkSeed : addressBytes (typed forsRoots a) { addressWord1 = addressWord1 a } : roots)
  where
    climbFors leafIndex index leaf siblings = go leaf leafIndex (P.zip [0 ..] siblings)
      where
        go current _ [] = current
        go current treeIndex ((j, sibling) : rest)
          | (index `Bits.shiftR` j) `P.mod` 2 == (0 :: Int) =
              let next = treeIndex `P.div` 2
              in go (hashN [pkSeed, at next j, current, sibling]) next rest
          | otherwise =
              let next = (treeIndex - 1) `P.div` 2
              in go (hashN [pkSeed, at next j, sibling, current]) next rest
        at next j = addressBytes a { addressWord2 = P.fromIntegral (j + 1 :: Int), addressWord3 = P.fromIntegral (next :: Int) }

digestIndices :: B.ByteString -> B.ByteString -> B.ByteString -> B.ByteString -> (B.ByteString, W.Word64, Int)
digestIndices r pkSeed pkRoot message =
  let digest = shake256Parts [r, pkSeed, pkRoot, message] slhM
      mdBytes = (slhK * slhA + 7) `P.div` 8
      treeBytes = (slhH - slhH `P.div` slhD + 7) `P.div` 8
      leafBytes = (slhH `P.div` slhD + 7) `P.div` 8
      number bytes = B.foldl' (\acc byte -> acc * 256 + P.toInteger byte) 0 bytes
      treeIndex = number (slice digest mdBytes treeBytes) `P.mod` 2 P.^ (slhH - slhH `P.div` slhD)
      leafIndex = number (slice digest (mdBytes + treeBytes) leafBytes) `P.mod` 2 P.^ (slhH `P.div` slhD)
  in (B.take mdBytes digest, P.fromInteger treeIndex, P.fromInteger leafIndex)

-- | slh_keygen_internal: the public key and the secret key.
slhDsaKeyPair :: B.ByteString -> B.ByteString -> B.ByteString -> (B.ByteString, B.ByteString)
slhDsaKeyPair skSeed skPrf pkSeed =
  let root = xmssNode skSeed 0 slhHp pkSeed zeroAddress { addressLayer = P.fromIntegral (slhD - 1) }
  in (pkSeed <> root, skSeed <> skPrf <> pkSeed <> root)

slhDsaSignInternal :: B.ByteString -> B.ByteString -> B.ByteString -> B.ByteString
slhDsaSignInternal message secretKey randomness =
  let [skSeed, skPrf, pkSeed, pkRoot] = [slice secretKey (i * slhN) slhN | i <- [0 .. 3]]
      r = hashN [skPrf, randomness, message]
      (digest, treeIndex, leafIndex) = digestIndices r pkSeed pkRoot message
      a = (typed forsTree zeroAddress { addressTree = treeIndex }) { addressWord1 = P.fromIntegral leafIndex }
      fors = forsSign digest skSeed pkSeed a
      forsPublic = forsPublicFromSignature fors digest pkSeed a
  in r <> fors <> htSign forsPublic skSeed pkSeed treeIndex leafIndex

slhDsaVerifyInternal :: B.ByteString -> B.ByteString -> B.ByteString -> Bool
slhDsaVerifyInternal message signature publicKey
  | B.length signature /= slhSignatureBytes || B.length publicKey /= 2 * slhN = False
  | otherwise =
      let (pkSeed, pkRoot) = B.splitAt slhN publicKey
          r = B.take slhN signature
          forsEnd = (1 + slhK * (1 + slhA)) * slhN
          (digest, treeIndex, leafIndex) = digestIndices r pkSeed pkRoot message
          a = (typed forsTree zeroAddress { addressTree = treeIndex }) { addressWord1 = P.fromIntegral leafIndex }
          forsPublic = forsPublicFromSignature (slice signature slhN (forsEnd - slhN)) digest pkSeed a
      in htVerify forsPublic (B.drop forsEnd signature) pkSeed treeIndex leafIndex pkRoot

pure' :: B.ByteString -> B.ByteString -> B.ByteString
pure' message ctx = B.pack [0, P.fromIntegral (B.length ctx)] <> ctx <> message

-- | slh_sign, hedged with fresh randomness.
slhDsaSign :: B.ByteString -> B.ByteString -> B.ByteString -> IO B.ByteString
slhDsaSign secretKey message ctx = do
  randomness <- Random.getRandomBytes slhN
  pure (slhDsaSignInternal (pure' message ctx) secretKey randomness)

slhDsaVerify :: B.ByteString -> B.ByteString -> B.ByteString -> B.ByteString -> Bool
slhDsaVerify publicKey message signature ctx = B.length ctx < 256 && slhDsaVerifyInternal (pure' message ctx) signature publicKey

-- The handlers.

-- | SHA3-256 and SHAKE256.
hashHandler :: P.IO Abilities.Hash
hashHandler = P.pure Abilities.Hash
  { Abilities.sha3 = \message -> pure (@@Digest@@ (sha3_256 message))
  , Abilities.shake = \message len -> pure (shake256 message (P.fromIntegral len))
  }

-- | ML-KEM-768.
keyExchangeHandler :: P.IO Abilities.KeyExchange
keyExchangeHandler = P.pure Abilities.KeyExchange
  { Abilities.exchangeKeyPair = do
      seed <- Random.getRandomBytes 64
      pure (@@ExchangeKeyPair@@ (@@ExchangePublicKey@@ (mlKem768PublicKey seed)) (@@ExchangeSecretKey@@ seed))
  , Abilities.encapsulate = \(@@ExchangePublicKey@@ publicKey) -> do
      (ciphertext, secret) <- mlKem768Encapsulate publicKey
      pure (@@Encapsulated@@ (@@Ciphertext@@ ciphertext) (@@SharedSecret@@ secret))
  , Abilities.decapsulate = \(@@ExchangeSecretKey@@ seed) (@@Ciphertext@@ ciphertext) ->
      pure (@@SharedSecret@@ (mlKem768Decapsulate seed ciphertext))
  }

-- | ML-DSA-65, hedged.
signatureHandler :: P.IO Abilities.Signature
signatureHandler = P.pure Abilities.Signature
  { Abilities.signingKeyPair = do
      seed <- Random.getRandomBytes 32
      pure (@@SigningKeyPair@@ (@@VerifyingKey@@ (mlDsa65PublicKey seed)) (@@SigningKey@@ seed))
  , Abilities.sign = \(@@SigningKey@@ seed) message -> @@SignatureBytes@@ P.<$> mlDsa65Sign seed message B.empty
  , Abilities.verify = \(@@VerifyingKey@@ publicKey) message (@@SignatureBytes@@ signature) ->
      pure (mlDsa65Verify publicKey message signature B.empty)
  }

-- | SLH-DSA-SHAKE-128f, hedged: the alternative Signature handler. Bind it
-- in lawspec.json: {"ability": "lawspec.crypto::Signature", "native":
-- ["Lawspec", "Crypto", "slhDsaSignatureHandler"]}.
slhDsaSignatureHandler :: P.IO Abilities.Signature
slhDsaSignatureHandler = P.pure Abilities.Signature
  { Abilities.signingKeyPair = do
      skSeed <- Random.getRandomBytes slhN
      skPrf <- Random.getRandomBytes slhN
      pkSeed <- Random.getRandomBytes slhN
      let (publicKey, secretKey) = slhDsaKeyPair skSeed skPrf pkSeed
      pure (@@SigningKeyPair@@ (@@VerifyingKey@@ publicKey) (@@SigningKey@@ secretKey))
  , Abilities.sign = \(@@SigningKey@@ secretKey) message -> @@SignatureBytes@@ P.<$> slhDsaSign secretKey message B.empty
  , Abilities.verify = \(@@VerifyingKey@@ publicKey) message (@@SignatureBytes@@ signature) ->
      pure (slhDsaVerify publicKey message signature B.empty)
  }

-- | AES-256-GCM, a fresh random nonce per message.
aeadHandler :: P.IO Abilities.Aead
aeadHandler = P.pure Abilities.Aead
  { Abilities.aeadKey = @@AeadKey@@ P.<$> Random.getRandomBytes 32
  , Abilities.deriveAeadKey = \(@@SharedSecret@@ secret) ctx -> pure (@@AeadKey@@ (shake256 (secret <> ctx) 32))
  , Abilities.seal = \(@@AeadKey@@ key) plaintext associated -> do
      nonce <- Random.getRandomBytes 12
      pure (@@Sealed@@ (nonce <> aes256GcmEncrypt key nonce plaintext associated))
  , Abilities.unseal = \(@@AeadKey@@ key) (@@Sealed@@ sealed) associated ->
      pure (if B.length sealed < 12 then Nothing else aes256GcmDecrypt key (B.take 12 sealed) (B.drop 12 sealed) associated)
  }
